head.script:
/* =====================================================================
 * THIẾT KẾ MẪU IN (NameCard / NamePlace)
 *   - Kéo thả phần tử trên trang (tọa độ mm), chỉnh thuộc tính, mẫu dựng sẵn
 *   - Chế độ HTML tùy biến ({{biến}})
 *   - Xem trước PDF thật trước khi lưu, lưu / nhân bản / xuất mẫu
 * API: /api/print-templates (API_GUEST.md mục 8)
 * ===================================================================== */
scwin.P = "pr";
/* =====================================================================
 * LỚP DÙNG CHUNG (giống các màn Hội trường / Sự kiện)
 *   - Phiên đăng nhập, quyền
 *   - Gọi API JSON bằng submission WebSquare (scwin.callApi)
 *   - Upload / tải file bằng XMLHttpRequest (submission không xử lý file nhị phân)
 * ===================================================================== */
scwin.API_BASE = "http://localhost:8081";
scwin.KEY = { TOKEN: "ssc_token", USER: "ssc_user", PERMS: "ssc_permissions", MENUS: "ssc_menus" };
scwin.LOGIN_PAGE = "/authPage/LoginPage.xml";
scwin.CTX = window.location.pathname.replace(/\/websquare\/websquare\.html.*$/, "");
scwin.SBM_TIMEOUT = 60000;
scwin.sbmQueue = {};
scwin.sbmJob = {};
scwin.toastTimer = null;

/* ---------- Tiện ích ---------- */
scwin.comp = function (id) { return $p.getComponentById(id); };
scwin.domOf = function (c) { return c ? (c.render || document.getElementById(c.id) || null) : null; };
scwin.show = function (c, v) { if (!c) return; if (v === false) c.addClass("is-hidden"); else c.removeClass("is-hidden"); };
scwin.toggleClass = function (c, cls, on) { if (!c) return; if (on) c.addClass(cls); else c.removeClass(cls); };
scwin.safeColor = function (c) { return /^#[0-9a-f]{3,8}$/i.test(String(c || "")) ? c : "#63746b"; };
scwin.trim = function (v) { return v == null ? "" : String(v).replace(/^\s+|\s+$/g, ""); };
scwin.dash = function (v) { return (v == null || scwin.trim(v) === "") ? "—" : String(v); };
scwin.pad = function (n) { return n < 10 ? "0" + n : String(n); };
scwin.clamp = function (v, a, b) { v = Number(v) || 0; a = a == null ? 0 : a; b = b == null ? 100 : b; return Math.max(a, Math.min(b, v)); };
scwin.hasOwn = function (o, k) { return o != null && Object.prototype.hasOwnProperty.call(o, k); };
scwin.fmtNumber = function (n) { return (n == null || n === "" || isNaN(Number(n))) ? "—" : Number(n).toLocaleString("vi-VN"); };
scwin.fmtRate = function (r) { return (Math.round((Number(r) || 0) * 10) / 10).toLocaleString("vi-VN") + "%"; };
scwin.fmtDate = function (s) { if (!s) return ""; var p = String(s).substring(0, 10).split("-"); return p.length === 3 ? p[2] + "/" + p[1] + "/" + p[0] : String(s); };
scwin.fmtTime = function (s) { return s ? String(s).substring(0, 5) : ""; };
scwin.fmtDateTime = function (iso) {
    if (!iso) return "—";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return String(iso);
    return scwin.pad(d.getDate()) + "/" + scwin.pad(d.getMonth() + 1) + "/" + d.getFullYear() + " " + scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes());
};
scwin.fmtClock = function (iso) {
    var d = iso ? new Date(iso) : new Date();
    if (isNaN(d.getTime())) d = new Date();
    return scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes()) + ":" + scwin.pad(d.getSeconds());
};
scwin.fmtSize = function (b) { return b >= 1048576 ? (b / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(b / 1024)) + " KB"; };
/** Tham số mảng được nối bằng dấu phẩy (backend nhận cả "A,B" lẫn lặp tham số). */
scwin.buildQuery = function (p) {
    var out = [];
    for (var k in p) {
        if (!p.hasOwnProperty(k)) continue;
        var v = p[k];
        if (Array.isArray(v)) { if (!v.length) continue; v = v.join(","); }
        if (v === null || v === undefined || v === "") continue;
        out.push(encodeURIComponent(k) + "=" + encodeURIComponent(v));
    }
    return out.join("&");
};
scwin.getQueryParam = function (name) {
    var m = new RegExp("[?&]" + name + "=([^&#]*)").exec(window.location.search);
    return m ? decodeURIComponent(m[1].replace(/\+/g, " ")) : "";
};
scwin.pageUrl = function (path, params) {
    var q = params ? scwin.buildQuery(params) : "";
    return scwin.CTX + "/websquare/websquare.html?w2xPath=" + scwin.CTX + path + (q ? "&" + q : "");
};
scwin.escHtml = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); };
scwin.el = function (tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
scwin.clearEl = function (el) { if (el) while (el.firstChild) el.removeChild(el.firstChild); };
scwin.fitGrid = function (grid, rows, rowH, maxRows) {
    var n = maxRows ? Math.min(rows, maxRows) : rows;
    grid.setStyle("height", (rows ? 42 + n * (rowH || 46) + 2 : 0) + "px");
    scwin.show(grid, rows > 0);
};
scwin.isTrue = function (v) { return v === true || v === "true" || v === 1 || v === "1"; };

/* ---------- Phiên đăng nhập & quyền ---------- */
scwin.storeGet = function (k) { try { return window.localStorage.getItem(k) || window.sessionStorage.getItem(k) || ""; } catch (e) { return ""; } };
scwin.parseJSON = function (t) { if (!t || typeof t !== "string") return null; try { return JSON.parse(t); } catch (e) { return null; } };
scwin.getToken = function () { return String(scwin.storeGet(scwin.KEY.TOKEN)).replace(/^Bearer\s+/i, ""); };
scwin.getPerms = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.PERMS)) || []; };
scwin.getUser = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.USER)) || {}; };
/** Header chưa kịp lưu quyền (lần đầu vào trang) thì tạm cho phép; backend vẫn chặn bằng 403. */
scwin.can = function (code) { var p = scwin.getPerms(); return !p.length || p.indexOf(code) >= 0; };
scwin.canAny = function (codes) { for (var i = 0; i < codes.length; i++) if (scwin.can(codes[i])) return true; return false; };
scwin.goLogin = function () {
    if (scwin._redirecting) return;
    scwin._redirecting = true;
    for (var k in scwin.KEY) {
        if (!scwin.KEY.hasOwnProperty(k)) continue;
        try { window.localStorage.removeItem(scwin.KEY[k]); window.sessionStorage.removeItem(scwin.KEY[k]); } catch (e) { }
    }
    window.location.href = scwin.pageUrl(scwin.LOGIN_PAGE);
};

/* ---------- Lỗi ---------- */
scwin.defaultMessage = function (status) {
    if (status === 0) return "Không kết nối được máy chủ. Kiểm tra mạng hoặc backend (" + scwin.API_BASE + ").";
    if (status === 401) return "Phiên đăng nhập đã hết hạn. Hãy đăng nhập lại.";
    if (status === 403) return "Tài khoản của bạn chưa được cấp quyền cho thao tác này.";
    if (status === 404) return "Không tìm thấy dữ liệu, hoặc dữ liệu nằm ngoài phạm vi bạn được xem.";
    if (status >= 500) return "Máy chủ đang gặp sự cố. Thử lại sau ít phút.";
    return "Yêu cầu không thành công (HTTP " + status + ").";
};
scwin.authHeader = function (accept) {
    var h = { "Accept": accept || "application/json" };
    var t = scwin.getToken();
    if (t) h["Authorization"] = "Bearer " + t;
    return h;
};
/** Chuẩn hóa lỗi: { status, code, message, data }. 401 thì đưa về trang đăng nhập. */
scwin.buildError = function (status, json) {
    var err = {
        status: status || 0,
        code: (json && json.code) || (status ? "HTTP_" + status : "NETWORK_ERROR"),
        message: (json && json.message) || scwin.defaultMessage(status || 0),
        data: json ? json.data : null
    };
    if (status === 401) {
        err.message = scwin.defaultMessage(401);
        scwin.toast(err.message + " Đang chuyển về trang đăng nhập…", "error");
        setTimeout(scwin.goLogin, 1500);
    }
    return err;
};

/* ---------- Submission ----------
 *   scwin.callApi("sbm_xxx", { url: "...", body: {...} }) -> Promise<data>
 *   Mỗi submission có hàng đợi riêng nên gọi chồng nhau không bị trả nhầm kết quả.
 */
scwin.callApi = function (sbmId, opts) {
    return new Promise(function (resolve, reject) {
        if (!scwin.sbmQueue[sbmId]) scwin.sbmQueue[sbmId] = [];
        scwin.sbmQueue[sbmId].push({ opts: opts || {}, resolve: resolve, reject: reject });
        scwin.sbmNext(sbmId);
    });
};
scwin.sbmNext = function (sbmId) {
    if (scwin.sbmJob[sbmId]) return;
    var q = scwin.sbmQueue[sbmId];
    if (!q || !q.length) return;
    var job = q.shift();
    scwin.sbmJob[sbmId] = job;
    var sbm = $p.getSubmission(sbmId);
    if (!sbm) { scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_NOT_FOUND", message: "Chưa khai báo submission " + sbmId + "." }); return; }
    sbm.action = job.opts.url;
    sbm.requestHeader = scwin.authHeader();
    job.timer = setTimeout(function () {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "TIMEOUT", message: "Máy chủ phản hồi quá lâu. Thử lại sau." });
    }, scwin.SBM_TIMEOUT);
    try {
        if (job.opts.body !== undefined) $p.executeSubmission(sbmId, job.opts.body);
        else $p.executeSubmission(sbmId);
    } catch (ex) {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_ERROR", message: (ex && ex.message) || String(ex) });
    }
};
scwin.sbmSettle = function (sbmId, data, err) {
    var job = scwin.sbmJob[sbmId];
    if (!job) return;
    clearTimeout(job.timer);
    scwin.sbmJob[sbmId] = null;
    if (err) job.reject(err); else job.resolve(data);
    scwin.sbmNext(sbmId);
};
scwin.readResponse = function (e) {
    if (!e) return null;
    if (e.responseJSON && typeof e.responseJSON === "object") return e.responseJSON;
    return scwin.parseJSON(e.responseText) || scwin.parseJSON(e.responseBody);
};
scwin.onSbmDone = function (sbmId, e) {
    var json = scwin.readResponse(e);
    if (json && json.success === false) { scwin.sbmSettle(sbmId, null, scwin.buildError((e && e.responseStatusCode) || 200, json)); return; }
    scwin.sbmSettle(sbmId, scwin.hasOwn(json, "data") ? json.data : json, null);
};
scwin.onSbmError = function (sbmId, e) {
    var status = (e && (e.responseStatusCode || e.status)) || 0;
    scwin.sbmSettle(sbmId, null, scwin.buildError(status, scwin.readResponse(e)));
};

/* ---------- XMLHttpRequest: upload multipart, nhận file ----------
 *   opts.body: object (gửi JSON) | FormData (multipart)
 *   opts.responseType: "json" (mặc định) | "blob" -> resolve { blob, name, type, headers }
 */
scwin.xhr = function (method, url, opts) {
    opts = opts || {};
    return new Promise(function (resolve, reject) {
        var x = new XMLHttpRequest();
        x.open(method, url);
        var h = scwin.authHeader(opts.responseType === "blob" ? "*/*" : "application/json");
        for (var k in h) if (h.hasOwnProperty(k)) x.setRequestHeader(k, h[k]);
        var body = null;
        if (typeof FormData !== "undefined" && opts.body instanceof FormData) body = opts.body;
        else if (opts.body !== undefined && opts.body !== null) { x.setRequestHeader("Content-Type", "application/json"); body = JSON.stringify(opts.body); }
        if (opts.responseType === "blob") x.responseType = "blob";
        if (opts.onProgress && x.upload) x.upload.onprogress = function (ev) { if (ev.lengthComputable) opts.onProgress(Math.round(ev.loaded * 100 / ev.total)); };
        x.onload = function () {
            var ok = x.status >= 200 && x.status < 300;
            if (opts.responseType === "blob") {
                var type = x.getResponseHeader("Content-Type") || "";
                if (ok && type.indexOf("application/json") < 0) {
                    resolve({ blob: x.response, type: type, name: scwin.fileNameFrom(x.getResponseHeader("Content-Disposition")), xhr: x });
                    return;
                }
                scwin.readBlobJSON(x.response).then(function (json) { reject(scwin.buildError(ok ? 200 : x.status, json)); });
                return;
            }
            var json = scwin.parseJSON(x.responseText);
            if (ok && !(json && json.success === false)) resolve(scwin.hasOwn(json, "data") ? json.data : json);
            else reject(scwin.buildError(x.status, json));
        };
        x.onerror = function () { reject(scwin.buildError(0, null)); };
        x.send(body);
    });
};
scwin.readBlobJSON = function (blob) {
    return new Promise(function (resolve) {
        if (!blob || typeof FileReader === "undefined") { resolve(null); return; }
        var r = new FileReader();
        r.onload = function () { resolve(scwin.parseJSON(r.result)); };
        r.onerror = function () { resolve(null); };
        r.readAsText(blob);
    });
};
scwin.fileNameFrom = function (cd) {
    if (!cd) return "";
    var m = /filename\*=UTF-8''([^;]+)/i.exec(cd) || /filename="?([^";]+)"?/i.exec(cd);
    if (!m) return "";
    try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
};
scwin.saveBlob = function (blob, name) {
    var url = URL.createObjectURL(blob);
    var a = scwin.el("a", scwin.P + "-native-link");
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(url); if (a.parentNode) a.parentNode.removeChild(a); }, 1500);
};
/** Tải file (GET hoặc POST kèm body JSON) rồi lưu về máy. */
scwin.downloadFile = function (url, fallbackName, btn, method, body) {
    if (btn) btn.addClass("is-busy");
    return scwin.xhr(method || "GET", url, { responseType: "blob", body: body }).then(function (r) {
        scwin.saveBlob(r.blob, r.name || fallbackName);
        return r;
    }).catch(function (err) {
        scwin.toast(err.message, "error");
        throw err;
    }).then(function (r) { if (btn) btn.removeClass("is-busy"); return r; }, function () { if (btn) btn.removeClass("is-busy"); });
};
/** In file PDF: nạp vào iframe ẩn rồi mở hộp thoại in của trình duyệt. */
scwin.printBlob = function (blob) {
    return new Promise(function (resolve) {
        var old = document.getElementById("ssc-print-frame");
        if (old) old.parentNode.removeChild(old);
        var url = URL.createObjectURL(blob);
        var f = document.createElement("iframe");
        f.id = "ssc-print-frame";
        f.className = scwin.P + "-print-frame";
        f.src = url;
        f.onload = function () {
            setTimeout(function () {
                try { f.contentWindow.focus(); f.contentWindow.print(); }
                catch (e) { window.open(url, "_blank"); }
                resolve();
            }, 300);
        };
        document.body.appendChild(f);
    });
};

/* ---------- Thông báo ---------- */
scwin.toast = function (msg, type) {
    if (typeof tbx_toast === "undefined") return;
    clearTimeout(scwin.toastTimer);
    tbx_toast.setValue(msg || "");
    ["success", "error", "warning", "info"].forEach(function (c) { tbx_toast.removeClass(scwin.P + "-toast--" + c); });
    tbx_toast.addClass(scwin.P + "-toast--" + (type || "info"));
    tbx_toast.addClass("is-show");
    scwin.toastTimer = setTimeout(function () { tbx_toast.removeClass("is-show"); }, (type === "error" || type === "warning") ? 6500 : 3800);
};
scwin.tbx_toast_onclick = function () { tbx_toast.removeClass("is-show"); };
scwin.showWarnings = function (list) {
    if (!list || !list.length) return;
    setTimeout(function () { scwin.toast("Lưu ý: " + list.join(" "), "warning"); }, 1800);
};

/* ---------- Danh mục dùng chung: GET /api/guests/lookups ---------- */
scwin.lookups = { events: [], guestTypes: [], guestStatuses: [] };
scwin.typeMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestTypes.length; i++) if (scwin.lookups.guestTypes[i].code === code) return scwin.lookups.guestTypes[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.statusMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestStatuses.length; i++) if (scwin.lookups.guestStatuses[i].code === code) return scwin.lookups.guestStatuses[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.GUEST_TYPE_VN = { VIP: "VIP", SPEAKER: "Diễn giả", GUEST: "Khách mời", STAFF: "Nhân viên", PRESS: "Báo chí", OTHER: "Khác" };
scwin.GUEST_STATUS_VN = { INVITED: "Đã mời", CONFIRMED: "Đã xác nhận", CHECKED_IN: "Đã check-in", ABSENT: "Vắng mặt" };
scwin.typeName = function (code) { return scwin.GUEST_TYPE_VN[code] || scwin.typeMeta(code).name; };
scwin.statusName = function (code) { return scwin.GUEST_STATUS_VN[code] || scwin.statusMeta(code).name; };
scwin.eventLabel = function (e) { return e.eventCode + " - " + e.eventName + (e.startDate ? " (" + scwin.fmtDate(e.startDate) + ")" : ""); };


scwin.TPL_API = scwin.API_BASE + "/api/print-templates";
scwin.GUEST_API = scwin.API_BASE + "/api/guests";
scwin.CENTER_PAGE = "/printPage/PrintCenter.xml";
scwin.MM_PX = 3.7795;           // 1 mm ở 100% (96 dpi)
scwin.PT_MM = 0.352778;         // 1 pt = 0.3528 mm
scwin.SNAP = 0.5;               // bước kéo thả (mm)
scwin.PAPER = { A4: [210, 297], A5: [148, 210], BADGE_3X4: [76.2, 101.6], BADGE_4X6: [101.6, 152.4] };
scwin.FIELDS = [
    { key: "fullName", label: "Họ tên", sample: "Nguyễn Thị Minh Khuê" },
    { key: "company", label: "Công ty", sample: "Công ty Cổ phần ABC" },
    { key: "position", label: "Chức vụ", sample: "Giám đốc kinh doanh" },
    { key: "guestType", label: "Loại khách", sample: "VIP" },
    { key: "tableNumber", label: "Bàn số", sample: "A1" },
    { key: "email", label: "Email", sample: "khue.nguyen@abc.vn" },
    { key: "phone", label: "Điện thoại", sample: "0901 234 567" },
    { key: "notes", label: "Ghi chú", sample: "Khách đi cùng 1 người" },
    { key: "eventName", label: "Tên sự kiện", sample: "Hội nghị khách hàng 2026" },
    { key: "eventCode", label: "Mã sự kiện", sample: "EVT00001" },
    { key: "text", label: "Chữ cố định", sample: "WELCOME" },
    { key: "qrCode", label: "Mã QR", image: true },
    { key: "photo", label: "Ảnh khách", image: true },
    { key: "eventLogo", label: "Logo sự kiện", image: true }
];
scwin.HTML_VARS = ["fullName", "company", "position", "guestType", "guestTypeCode", "guestTypeColor", "tableNumber", "email", "phone", "notes", "eventName", "eventCode", "qrCode", "eventLogo", "photo"];
scwin.TPL_DEFAULT = {
    templateName: "", templateType: "NAMECARD", paperSize: "BADGE_3X4", widthMm: "", heightMm: "", orientation: "PORTRAIT",
    marginTopMm: "3", marginRightMm: "3", marginBottomMm: "3", marginLeftMm: "3", fontFamily: "DejaVu Sans",
    primaryColor: "#0b3d2a", backgroundColor: "#FFFFFF", backgroundImageUrl: "", borderStyle: "none", dpi: "300", systemDefault: "", htmlTemplate: ""
};

scwin.tplId = null;
scwin.tpl = null;               // dữ liệu mẫu từ server (khi sửa)
scwin.mode = "layout";          // layout | html
scwin.els = [];
scwin.sel = -1;
scwin.scale = 3;
scwin.dirty = false;
scwin.drag = null;
scwin.pdfUrl = null;
scwin.open = { pv: false, preset: false };

/* =====================================================================
 * VÒNG ĐỜI
 * ===================================================================== */
scwin.onpageload = function () {
    if (!scwin.getToken()) { scwin.goLogin(); return; }
    if (!scwin.can("TEMPLATE_MANAGE")) scwin.toast("Bạn chỉ có quyền xem mẫu in. Thay đổi sẽ không lưu được.", "warning");
    scwin.handlers();
    scwin.renderPalette();
    scwin.renderVarChips();
    dma_tpl.setJSON(scwin.copy(scwin.TPL_DEFAULT));
    sbx_zoom.setValue("fit");
    scwin.tplId = scwin.getQueryParam("templateId") || null;
    scwin.loadLookups();
    if (scwin.tplId) scwin.loadTemplate(scwin.tplId);
    else { scwin.applyPreset("badgeBasic", true); scwin.openPreset(); }
    scwin.selectEl(-1);
    scwin.setMode("layout");
};
scwin.onpageunload = function () {
    document.removeEventListener("keydown", scwin.keyHandler);
    window.removeEventListener("resize", scwin.resizeHandler);
    window.removeEventListener("beforeunload", scwin.unloadHandler);
    document.removeEventListener("pointermove", scwin.moveHandler);
    document.removeEventListener("pointerup", scwin.upHandler);
};
scwin.handlers = function () {
    scwin.keyHandler = function (e) { scwin.onGlobalKeydown(e); };
    scwin.resizeHandler = function () { if (sbx_zoom.getValue() === "fit") scwin.renderCanvas(); };
    scwin.unloadHandler = function (e) { if (scwin.dirty) { e.preventDefault(); e.returnValue = ""; } };
    scwin.moveHandler = function (e) { scwin.onPointerMove(e); };
    scwin.upHandler = function (e) { scwin.onPointerUp(e); };
    document.addEventListener("keydown", scwin.keyHandler);
    window.addEventListener("resize", scwin.resizeHandler);
    window.addEventListener("beforeunload", scwin.unloadHandler);
    document.addEventListener("pointermove", scwin.moveHandler);
    document.addEventListener("pointerup", scwin.upHandler);
};
scwin.copy = function (o) { return JSON.parse(JSON.stringify(o)); };
scwin.num = function (v, d) { var n = parseFloat(String(v == null ? "" : v).replace(",", ".")); return isNaN(n) ? d : n; };
scwin.round = function (v) { return Math.round(v * 10) / 10; };

scwin.loadLookups = function () {
    scwin.callApi("sbm_lookups", { url: scwin.GUEST_API + "/lookups" }).then(function (d) {
        var ev = (d && d.events) || [];
        dlt_events.setJSON(ev.map(function (e) { return { eventId: String(e.eventId), label: scwin.eventLabel(e) }; }));
        var q = scwin.getQueryParam("eventId");
        if (q) sbx_pvEvent.setValue(q);
    }).catch(function () { });
};

scwin.loadTemplate = function (id) {
    grp_stage.addClass("is-loading");
    scwin.callApi("sbm_tplGet", { url: scwin.TPL_API + "/" + id }).then(function (t) { scwin.fillTemplate(t); })
        .catch(function (err) { scwin.toast(err.message, "error"); })
        .then(function () { grp_stage.removeClass("is-loading"); });
};
scwin.fillTemplate = function (t) {
    scwin.tpl = t;
    scwin.tplId = t.templateId;
    var s = function (v) { return v == null ? "" : String(v); };
    dma_tpl.setJSON({
        templateName: s(t.templateName), templateType: s(t.templateType), paperSize: s(t.paperSize), widthMm: s(t.widthMm), heightMm: s(t.heightMm),
        orientation: s(t.orientation || "PORTRAIT"), marginTopMm: s(t.marginTopMm), marginRightMm: s(t.marginRightMm), marginBottomMm: s(t.marginBottomMm),
        marginLeftMm: s(t.marginLeftMm), fontFamily: s(t.fontFamily || "DejaVu Sans"), primaryColor: s(t.primaryColor || "#000000"),
        backgroundColor: s(t.backgroundColor || "#FFFFFF"), backgroundImageUrl: s(t.backgroundImageUrl), borderStyle: s(t.borderStyle || "none"),
        dpi: s(t.dpi || 300), systemDefault: t.systemDefault ? "true" : "", htmlTemplate: s(t.htmlTemplate)
    });
    scwin.els = (t.layoutConfig && t.layoutConfig.elements) ? scwin.copy(t.layoutConfig.elements) : [];
    scwin.setMode(t.htmlTemplate ? "html" : "layout");
    scwin.selectEl(-1);
    scwin.updateTplUi();
    scwin.setDirty(false);
    tbx_dCrumb.setValue("In ấn / Mẫu in / " + (t.systemDefault ? "Mẫu mặc định hệ thống" : "Sửa mẫu #" + t.templateId));
    tbx_dMeta.setValue("Đang dùng bởi " + (t.usedByEventCount || 0) + " sự kiện. Cập nhật lúc " + scwin.fmtDateTime(t.updatedAt) + ".");
};

/* =====================================================================
 * THUỘC TÍNH MẪU
 * ===================================================================== */
scwin.syncTpl = function () {
    var map = { templateName: ibx_name, widthMm: ibx_w, heightMm: ibx_h, marginTopMm: ibx_mTop, marginRightMm: ibx_mRight,
        marginBottomMm: ibx_mBottom, marginLeftMm: ibx_mLeft, primaryColor: ibx_primary, backgroundColor: ibx_bg,
        backgroundImageUrl: ibx_bgImage, dpi: ibx_dpi, htmlTemplate: txa_html };
    for (var k in map) if (map.hasOwnProperty(k)) { var v = map[k].getValue(); if (v != null && dma_tpl.get(k) !== v) dma_tpl.set(k, v); }
};
scwin.pageSize = function () {
    var t = dma_tpl.getJSON();
    if (t.paperSize === "CUSTOM") return { w: scwin.clamp(scwin.num(t.widthMm, 80), 10, 1000), h: scwin.clamp(scwin.num(t.heightMm, 50), 10, 1000) };
    var p = scwin.PAPER[t.paperSize] || scwin.PAPER.BADGE_3X4;
    return t.orientation === "LANDSCAPE" ? { w: p[1], h: p[0] } : { w: p[0], h: p[1] };
};
scwin.updateTplUi = function () {
    var t = dma_tpl.getJSON(), custom = t.paperSize === "CUSTOM";
    scwin.show(grp_customSize, custom);
    scwin.show(grp_orient, !custom);
    grp_swPrimary.setStyle("background-color", scwin.safeColor(t.primaryColor));
    grp_swBg.setStyle("background-color", scwin.safeColor(t.backgroundColor));
    var s = scwin.pageSize();
    tbx_pageSize.setValue(scwin.round(s.w) + " × " + scwin.round(s.h) + " mm");
    tbx_dTitle.setValue(t.templateName || "Mẫu chưa đặt tên");
    scwin.renderCanvas();
};
scwin.tpl_onchange = function () { scwin.syncTpl(); scwin.setDirty(true); scwin.updateTplUi(); };
scwin.sbx_paper_onchange = function () {
    dma_tpl.set("paperSize", sbx_paper.getValue());
    if (sbx_paper.getValue() === "CUSTOM" && !dma_tpl.get("widthMm")) { var s = scwin.pageSize(); dma_tpl.set("widthMm", String(s.w)); dma_tpl.set("heightMm", String(s.h)); }
    scwin.tpl_onchange();
};
scwin.sbx_type_onchange = function () {
    var type = sbx_type.getValue();
    dma_tpl.set("templateType", type);
    // Gợi ý khổ giấy hợp loại
    var p = dma_tpl.get("paperSize");
    if (type === "NAMEPLACE" && (p === "BADGE_3X4" || p === "BADGE_4X6")) { dma_tpl.set("paperSize", "A4"); dma_tpl.set("orientation", "LANDSCAPE"); }
    if (type === "NAMECARD" && (p === "A4" || p === "A5")) { dma_tpl.set("paperSize", "BADGE_3X4"); dma_tpl.set("orientation", "PORTRAIT"); }
    scwin.tpl_onchange();
};

/* =====================================================================
 * CHẾ ĐỘ: KÉO THẢ / HTML
 * ===================================================================== */
scwin.setMode = function (m) {
    scwin.mode = m;
    scwin.toggleClass(btn_modeLayout, "is-selected", m === "layout");
    scwin.toggleClass(btn_modeHtml, "is-selected", m === "html");
    scwin.show(grp_layoutMode, m === "layout");
    scwin.show(grp_htmlMode, m === "html");
    scwin.show(grp_elPanel, m === "layout");
    if (m === "layout") setTimeout(scwin.renderCanvas, 30);
};
scwin.btn_modeLayout_onclick = function () {
    if (scwin.mode === "layout") return;
    scwin.setMode("layout"); scwin.setDirty(true);
};
scwin.btn_modeHtml_onclick = function () {
    if (scwin.mode === "html") return;
    if (!scwin.trim(txa_html.getValue())) {
        // Gợi ý sẵn một HTML tối thiểu
        dma_tpl.set("htmlTemplate", "<div style=\"text-align:center;padding-top:20mm;color:{{guestTypeColor}}\">\n  <div style=\"font-size:22pt;font-weight:bold\">{{fullName}}</div>\n  <div style=\"font-size:12pt\">{{company}}</div>\n  <img src=\"{{qrCode}}\" style=\"width:30mm;height:30mm;margin-top:8mm\"/>\n</div>");
    }
    scwin.setMode("html"); scwin.setDirty(true);
};
scwin.renderVarChips = function () {
    var box = scwin.domOf(grp_vars);
    scwin.clearEl(box);
    scwin.HTML_VARS.forEach(function (v) {
        var b = scwin.el("button", "pr-varchip", "{{" + v + "}}");
        b.type = "button";
        b.title = "Chèn vào vị trí con trỏ";
        b.addEventListener("click", function () { scwin.insertVar("{{" + v + "}}"); });
        box.appendChild(b);
    });
};
scwin.insertVar = function (txt) {
    var host = scwin.domOf(txa_html), ta = host && (host.tagName === "TEXTAREA" ? host : host.querySelector("textarea"));
    if (!ta) { txa_html.setValue((txa_html.getValue() || "") + txt); return; }
    var s = ta.selectionStart || 0, e = ta.selectionEnd || 0, v = ta.value;
    ta.value = v.substring(0, s) + txt + v.substring(e);
    ta.selectionStart = ta.selectionEnd = s + txt.length;
    ta.focus();
    dma_tpl.set("htmlTemplate", ta.value);
    scwin.setDirty(true);
};
scwin.txa_html_onkeyup = function () { scwin.setDirty(true); };

/* =====================================================================
 * PHẦN TỬ: THÊM, CHỌN, SỬA
 * ===================================================================== */
scwin.fieldDef = function (k) { for (var i = 0; i < scwin.FIELDS.length; i++) if (scwin.FIELDS[i].key === k) return scwin.FIELDS[i]; return { key: k, label: k, sample: k }; };
scwin.renderPalette = function () {
    var box = scwin.domOf(grp_palette);
    scwin.clearEl(box);
    scwin.FIELDS.forEach(function (f) {
        var b = scwin.el("button", "pr-palette__item" + (f.image ? " pr-palette__item--image" : ""), f.label);
        b.type = "button";
        b.title = "Thêm " + f.label.toLowerCase() + " vào giữa trang";
        b.addEventListener("click", function () { scwin.addElement(f.key); });
        box.appendChild(b);
    });
};
scwin.addElement = function (key) {
    var f = scwin.fieldDef(key), s = scwin.pageSize();
    var w = f.image ? Math.min(30, s.w - 6) : Math.min(scwin.round(s.w * 0.8), s.w - 6);
    var h = f.image ? w : 10;
    var el = { field: key, x: scwin.round((s.w - w) / 2), y: scwin.round((s.h - h) / 2), width: scwin.round(w), height: scwin.round(h) };
    if (!f.image) { el.fontSize = key === "fullName" ? 20 : 12; el.align = "center"; el.fontWeight = key === "fullName" ? "bold" : "normal"; }
    if (key === "text") el.text = "Nội dung";
    if (key === "tableNumber") el.prefix = "Bàn ";
    if (key === "guestType") { el.useTypeColor = true; el.color = "#FFFFFF"; el.uppercase = true; }
    scwin.els.push(el);
    scwin.selectEl(scwin.els.length - 1);
    scwin.setDirty(true);
};

scwin.selectEl = function (i) {
    scwin.sel = i;
    var el = scwin.els[i];
    scwin.show(grp_elForm, !!el);
    scwin.show(grp_elNone, !el);
    if (el) {
        var f = scwin.fieldDef(el.field), s = function (v) { return v == null ? "" : String(v); };
        dma_el.setJSON({
            field: el.field, text: s(el.text), prefix: s(el.prefix), x: s(el.x), y: s(el.y), width: s(el.width), height: s(el.height),
            fontSize: s(el.fontSize || 12), fontWeight: el.fontWeight || "normal", fontStyle: el.fontStyle || "normal", align: el.align || "left",
            color: s(el.color), backgroundColor: s(el.backgroundColor),
            flags: [el.uppercase ? "uppercase" : "", el.useTypeColor ? "useTypeColor" : "", el.visible === false ? "hidden" : ""].filter(function (x) { return !!x; }).join(",")
        });
        tbx_elTitle.setValue(f.label);
        scwin.show(grp_elText, el.field === "text");
        scwin.show(grp_elTextStyle, !f.image);
        scwin.show(grp_elPrefix, !f.image && el.field !== "text");
        tbx_elTypeHint.setValue(el.field === "guestType" ? "Tích “Tô nền theo màu loại khách” để có thẻ VIP vàng, Staff xanh…" : f.image ? "Ảnh co vừa khung, giữ tỉ lệ, căn giữa." : "Chữ dài tự thu nhỏ và xuống dòng cho vừa khung khi in.");
    }
    scwin.renderCanvas();
    scwin.renderLayers();
};
/** Đọc bảng thuộc tính -> phần tử đang chọn. */
scwin.el_onchange = function () {
    var el = scwin.els[scwin.sel];
    if (!el) return;
    var map = { text: ibx_elText, prefix: ibx_elPrefix, x: ibx_elX, y: ibx_elY, width: ibx_elW, height: ibx_elH, fontSize: ibx_elFont, color: ibx_elColor, backgroundColor: ibx_elBg };
    for (var k in map) if (map.hasOwnProperty(k)) { var v = map[k].getValue(); if (v != null && dma_el.get(k) !== v) dma_el.set(k, v); }
    var d = dma_el.getJSON(), flags = String(chk_elFlags.getValue() || "").split(/[\s,]+/);
    el.x = scwin.num(d.x, el.x); el.y = scwin.num(d.y, el.y);
    el.width = Math.max(1, scwin.num(d.width, el.width)); el.height = Math.max(1, scwin.num(d.height, el.height));
    var f = scwin.fieldDef(el.field);
    if (!f.image) {
        el.fontSize = scwin.clamp(scwin.num(d.fontSize, 12), 4, 200);
        el.fontWeight = sbx_elWeight.getValue() || "normal";
        el.fontStyle = sbx_elStyle.getValue() || "normal";
        el.align = sbx_elAlign.getValue() || "left";
        el.uppercase = flags.indexOf("uppercase") >= 0 || undefined;
        el.color = /^#[0-9a-f]{6}$/i.test(d.color) ? d.color : undefined;
        el.backgroundColor = /^#[0-9a-f]{6}$/i.test(d.backgroundColor) ? d.backgroundColor : undefined;
        el.prefix = d.prefix || undefined;
        if (el.field === "text") el.text = d.text;
        if (el.field === "guestType") el.useTypeColor = flags.indexOf("useTypeColor") >= 0 || undefined;
    }
    el.visible = flags.indexOf("hidden") >= 0 ? false : undefined;
    scwin.setDirty(true);
    scwin.renderCanvas();
    scwin.renderLayers();
};
scwin.btn_elDelete_onclick = function () {
    if (scwin.sel < 0) return;
    scwin.els.splice(scwin.sel, 1);
    scwin.selectEl(-1); scwin.setDirty(true);
};
scwin.btn_elDup_onclick = function () {
    var el = scwin.els[scwin.sel];
    if (!el) return;
    var c = scwin.copy(el), s = scwin.pageSize();
    c.x = Math.min(scwin.round(c.x + 3), s.w - c.width); c.y = Math.min(scwin.round(c.y + 3), s.h - c.height);
    scwin.els.push(c);
    scwin.selectEl(scwin.els.length - 1); scwin.setDirty(true);
};
scwin.btn_elCenter_onclick = function () {
    var el = scwin.els[scwin.sel];
    if (!el) return;
    el.x = scwin.round((scwin.pageSize().w - el.width) / 2);
    scwin.selectEl(scwin.sel); scwin.setDirty(true);
};
scwin.btn_elFull_onclick = function () {
    var el = scwin.els[scwin.sel];
    if (!el) return;
    var t = dma_tpl.getJSON(), s = scwin.pageSize(), l = scwin.num(t.marginLeftMm, 0), r = scwin.num(t.marginRightMm, 0);
    el.x = l; el.width = scwin.round(s.w - l - r);
    scwin.selectEl(scwin.sel); scwin.setDirty(true);
};
scwin.moveLayer = function (dir) {
    var i = scwin.sel, j = i + dir;
    if (i < 0 || j < 0 || j >= scwin.els.length) return;
    var t = scwin.els[i]; scwin.els[i] = scwin.els[j]; scwin.els[j] = t;
    scwin.selectEl(j); scwin.setDirty(true);
};
scwin.btn_elUp_onclick = function () { scwin.moveLayer(1); };
scwin.btn_elDown_onclick = function () { scwin.moveLayer(-1); };

/* ---------- Danh sách lớp ---------- */
scwin.renderLayers = function () {
    var box = scwin.domOf(grp_layers);
    if (!box) return;
    scwin.clearEl(box);
    if (!scwin.els.length) { box.appendChild(scwin.el("p", "pr-layers__empty", "Chưa có phần tử. Chọn trường ở trên để thêm.")); return; }
    var s = scwin.pageSize();
    for (var i = scwin.els.length - 1; i >= 0; i--) {
        (function (i) {
            var el = scwin.els[i], f = scwin.fieldDef(el.field);
            var out = scwin.isOut(el, s);
            var b = scwin.el("button", "pr-layer" + (i === scwin.sel ? " is-selected" : "") + (out ? " is-out" : "") + (el.visible === false ? " is-hidden-el" : ""));
            b.type = "button";
            b.appendChild(scwin.el("span", "pr-layer__name", f.label + (el.field === "text" && el.text ? ": " + el.text : "")));
            b.appendChild(scwin.el("span", "pr-layer__meta", out ? "Ra ngoài trang" : scwin.round(el.x) + ", " + scwin.round(el.y)));
            b.addEventListener("click", function () { scwin.selectEl(i); });
            box.appendChild(b);
        })(i);
    }
};
scwin.isOut = function (el, s) { return el.x < -0.01 || el.y < -0.01 || el.x + el.width > s.w + 0.01 || el.y + el.height > s.h + 0.01; };

/* =====================================================================
 * CANVAS
 * ===================================================================== */
scwin.sbx_zoom_onchange = function () { scwin.renderCanvas(); };
scwin.renderCanvas = function () {
    if (scwin.mode !== "layout") return;
    var stage = scwin.domOf(grp_stage);
    if (!stage) return;
    var t = dma_tpl.getJSON(), s = scwin.pageSize(), z = sbx_zoom.getValue() || "fit";
    var avW = Math.max(200, stage.clientWidth - 56), avH = Math.max(240, stage.clientHeight - 56);
    scwin.scale = z === "fit" ? Math.min(avW / s.w, avH / s.h, 8) : scwin.MM_PX * Number(z) / 100;
    var k = scwin.scale;
    var page = scwin.pageEl;
    if (!page) {
        page = scwin.el("div", "pr-page");
        page.addEventListener("pointerdown", function (e) { if (e.target === page || e.target.className === "pr-page__margin") scwin.selectEl(-1); });
        stage.appendChild(page);
        scwin.pageEl = page;
    }
    page.style.width = (s.w * k) + "px";
    page.style.height = (s.h * k) + "px";
    page.style.backgroundColor = scwin.safeColor(t.backgroundColor);
    page.style.backgroundImage = t.backgroundImageUrl ? "url(\"" + String(t.backgroundImageUrl).replace(/"/g, "") + "\")" : "none";
    page.style.borderStyle = t.borderStyle && t.borderStyle !== "none" ? t.borderStyle : "solid";
    page.style.borderColor = t.borderStyle && t.borderStyle !== "none" ? scwin.safeColor(t.primaryColor) : "transparent";
    page.style.color = scwin.safeColor(t.primaryColor);
    scwin.clearEl(page);

    var m = scwin.el("div", "pr-page__margin");
    m.style.left = scwin.num(t.marginLeftMm, 0) * k + "px"; m.style.top = scwin.num(t.marginTopMm, 0) * k + "px";
    m.style.right = scwin.num(t.marginRightMm, 0) * k + "px"; m.style.bottom = scwin.num(t.marginBottomMm, 0) * k + "px";
    page.appendChild(m);

    scwin.els.forEach(function (el, i) {
        var f = scwin.fieldDef(el.field);
        var d = scwin.el("div", "pr-el" + (f.image ? " pr-el--image pr-el--" + el.field : "") + (i === scwin.sel ? " is-selected" : "")
            + (scwin.isOut(el, s) ? " is-out" : "") + (el.visible === false ? " is-hidden-el" : ""));
        d.style.left = el.x * k + "px"; d.style.top = el.y * k + "px";
        d.style.width = el.width * k + "px"; d.style.height = el.height * k + "px";
        if (f.image) {
            d.appendChild(scwin.el("span", "pr-el__label", f.label));
        } else {
            var txt = (el.prefix || "") + (el.field === "text" ? (el.text || "") : f.sample);
            var span = scwin.el("span", "pr-el__text", el.uppercase ? txt.toUpperCase() : txt);
            d.style.fontSize = (scwin.num(el.fontSize, 12) * scwin.PT_MM * k) + "px";
            d.style.fontWeight = el.fontWeight === "bold" ? "700" : "400";
            d.style.fontStyle = el.fontStyle === "italic" ? "italic" : "normal";
            d.style.justifyContent = el.align === "center" ? "center" : el.align === "right" ? "flex-end" : "flex-start";
            d.style.textAlign = el.align || "left";
            if (el.color) d.style.color = el.color;
            if (el.useTypeColor) d.style.backgroundColor = "#D4AF37";
            else if (el.backgroundColor) d.style.backgroundColor = el.backgroundColor;
            d.appendChild(span);
        }
        var hdl = scwin.el("span", "pr-el__handle");
        d.appendChild(hdl);
        d.addEventListener("pointerdown", function (e) { scwin.onPointerDown(e, i, e.target === hdl ? "resize" : "move"); });
        page.appendChild(d);
    });
    var outN = scwin.els.filter(function (el) { return scwin.isOut(el, s); }).length;
    tbx_canvasWarn.setValue(outN ? outN + " phần tử nằm ngoài trang. Kéo vào trong hoặc chỉnh lại tọa độ trước khi lưu." : "");
    scwin.show(tbx_canvasWarn, outN > 0);
};

/* ---------- Kéo thả & co giãn (đơn vị mm, bước 0.5 mm) ---------- */
scwin.snap = function (v) { return Math.round(v / scwin.SNAP) * scwin.SNAP; };
scwin.onPointerDown = function (e, i, kind) {
    e.preventDefault();
    e.stopPropagation();
    if (scwin.sel !== i) scwin.selectEl(i);
    var el = scwin.els[i];
    scwin.drag = { i: i, kind: kind, mx: e.clientX, my: e.clientY, x: el.x, y: el.y, w: el.width, h: el.height, moved: false };
    scwin.canvasActive = true;
};
scwin.onPointerMove = function (e) {
    var d = scwin.drag;
    if (!d) return;
    var el = scwin.els[d.i], s = scwin.pageSize(), k = scwin.scale;
    var dx = (e.clientX - d.mx) / k, dy = (e.clientY - d.my) / k;
    if (Math.abs(dx) + Math.abs(dy) > 0.3) d.moved = true;
    if (d.kind === "move") {
        el.x = scwin.clamp(scwin.snap(d.x + dx), 0, Math.max(0, s.w - el.width));
        el.y = scwin.clamp(scwin.snap(d.y + dy), 0, Math.max(0, s.h - el.height));
    } else {
        el.width = scwin.clamp(scwin.snap(d.w + dx), 2, s.w - el.x);
        el.height = scwin.clamp(scwin.snap(d.h + dy), 2, s.h - el.y);
    }
    var node = scwin.pageEl && scwin.pageEl.querySelectorAll(".pr-el")[d.i];
    if (node) {
        node.style.left = el.x * k + "px"; node.style.top = el.y * k + "px";
        node.style.width = el.width * k + "px"; node.style.height = el.height * k + "px";
    }
    tbx_dragInfo.setValue("x " + el.x + ", y " + el.y + ", " + el.width + " × " + el.height + " mm");
};
scwin.onPointerUp = function () {
    var d = scwin.drag;
    if (!d) return;
    scwin.drag = null;
    tbx_dragInfo.setValue("");
    if (d.moved) { scwin.setDirty(true); scwin.selectEl(d.i); }
};

/* =====================================================================
 * MẪU DỰNG SẴN
 * ===================================================================== */
scwin.PRESETS = {
    badgeBasic: { name: "Thẻ tên cơ bản", type: "NAMECARD", paper: "BADGE_3X4", orient: "PORTRAIT", els: [
        { field: "eventName", x: 4, y: 5, width: 68.2, height: 8, fontSize: 9, align: "center", uppercase: true },
        { field: "guestType", x: 0, y: 15, width: 76.2, height: 9, fontSize: 12, fontWeight: "bold", align: "center", color: "#FFFFFF", useTypeColor: true, uppercase: true },
        { field: "fullName", x: 4, y: 30, width: 68.2, height: 16, fontSize: 18, fontWeight: "bold", align: "center" },
        { field: "position", x: 4, y: 47, width: 68.2, height: 6, fontSize: 10, align: "center", fontStyle: "italic" },
