scwin.applyPreset = function (key, silent) {
    var p = scwin.PRESETS[key];
    if (!p) return;
    if (p.type) {
        dma_tpl.set("templateType", p.type); dma_tpl.set("paperSize", p.paper); dma_tpl.set("orientation", p.orient);
        if (!dma_tpl.get("templateName")) dma_tpl.set("templateName", p.name);
    }
    scwin.els = scwin.copy(p.els);
    scwin.selectEl(-1);
    scwin.updateTplUi();
    if (!silent) scwin.setDirty(true);
};
scwin.openPreset = function () { scwin.open.preset = true; grp_presetMask.addClass("is-open"); };
scwin.closePreset = function () { scwin.open.preset = false; grp_presetMask.removeClass("is-open"); };
scwin.btn_presets_onclick = function () {
    if (scwin.els.length && !window.confirm("Áp dụng mẫu dựng sẵn sẽ thay toàn bộ phần tử hiện có. Tiếp tục?")) return;
    scwin.openPreset();
};
scwin.btn_pBadge_onclick = function () { dma_tpl.set("templateName", ""); scwin.applyPreset("badgeBasic"); scwin.closePreset(); };
scwin.btn_pVip_onclick = function () { dma_tpl.set("templateName", ""); scwin.applyPreset("badgeVip"); scwin.closePreset(); };
scwin.btn_pPlace_onclick = function () { dma_tpl.set("templateName", ""); scwin.applyPreset("nameplace"); scwin.closePreset(); };
scwin.btn_pBlank_onclick = function () { scwin.applyPreset("blank"); scwin.closePreset(); };

/* =====================================================================
 * LƯU, XEM TRƯỚC, NHÂN BẢN, XUẤT
 * ===================================================================== */
scwin.setDirty = function (on) {
    scwin.dirty = on;
    tbx_dStatus.setValue(on ? "Chưa lưu" : (scwin.tplId ? "Đã lưu" : "Mẫu mới"));
    scwin.toggleClass(tbx_dStatus, "is-dirty", on);
};
scwin.cleanEl = function (el) {
    var o = {};
    ["field", "text", "prefix", "x", "y", "width", "height", "fontSize", "fontWeight", "fontStyle", "fontFamily", "color", "backgroundColor", "align", "uppercase", "useTypeColor", "visible"]
        .forEach(function (k) { if (el[k] !== undefined && el[k] !== null && el[k] !== "") o[k] = el[k]; });
    ["x", "y", "width", "height"].forEach(function (k) { o[k] = scwin.round(Number(o[k]) || 0); });
    return o;
};
scwin.buildBody = function () {
    scwin.syncTpl();
    var t = dma_tpl.getJSON(), custom = t.paperSize === "CUSTOM";
    return {
        templateName: scwin.trim(t.templateName), templateType: t.templateType, paperSize: t.paperSize,
        widthMm: custom ? scwin.num(t.widthMm, null) : null, heightMm: custom ? scwin.num(t.heightMm, null) : null,
        orientation: t.orientation || "PORTRAIT",
        marginTopMm: scwin.num(t.marginTopMm, 0), marginRightMm: scwin.num(t.marginRightMm, 0),
        marginBottomMm: scwin.num(t.marginBottomMm, 0), marginLeftMm: scwin.num(t.marginLeftMm, 0),
        fontFamily: t.fontFamily || "DejaVu Sans",
        primaryColor: /^#[0-9a-f]{6}$/i.test(t.primaryColor) ? t.primaryColor : null,
        backgroundColor: /^#[0-9a-f]{6}$/i.test(t.backgroundColor) ? t.backgroundColor : null,
        backgroundImageUrl: scwin.trim(t.backgroundImageUrl) || null,
        borderStyle: t.borderStyle || "none", dpi: scwin.num(t.dpi, 300),
        systemDefault: !!String(t.systemDefault || ""),
        htmlTemplate: scwin.mode === "html" ? t.htmlTemplate : null,
        layoutConfig: scwin.mode === "layout" ? { elements: scwin.els.map(scwin.cleanEl) } : null
    };
};
scwin.validate = function (b) {
    var e = [];
    if (!b.templateName) e.push("Nhập tên mẫu.");
    if (b.paperSize === "CUSTOM" && (!(b.widthMm >= 10 && b.widthMm <= 1000) || !(b.heightMm >= 10 && b.heightMm <= 1000))) e.push("Khổ tùy chỉnh phải từ 10 đến 1000 mm.");
    if (!(b.dpi >= 72 && b.dpi <= 1200)) e.push("DPI từ 72 đến 1200.");
    if (b.layoutConfig) {
        if (!b.layoutConfig.elements.length) e.push("Mẫu chưa có phần tử nào.");
        if (b.layoutConfig.elements.length > 50) e.push("Tối đa 50 phần tử.");
        var s = scwin.pageSize();
        if (scwin.els.some(function (el) { return scwin.isOut(el, s); })) e.push("Có phần tử nằm ngoài trang.");
        if (scwin.els.some(function (el) { return el.field === "text" && !scwin.trim(el.text); })) e.push("Phần tử Chữ cố định chưa có nội dung.");
    } else if (!scwin.trim(b.htmlTemplate)) e.push("Nhập nội dung HTML.");
    return e;
};
scwin.showErrors = function (list) {
    tbx_saveErr.setValue(list.join("\n"));
    scwin.show(tbx_saveErr, list.length > 0);
};

scwin.btn_save_onclick = function () {
    var b = scwin.buildBody(), errs = scwin.validate(b);
    scwin.showErrors(errs);
    if (errs.length) { scwin.toast(errs[0], "warning"); return; }
    btn_save.addClass("is-busy");
    (scwin.tplId
        ? scwin.callApi("sbm_tplUpdate", { url: scwin.TPL_API + "/" + scwin.tplId, body: b })
        : scwin.callApi("sbm_tplCreate", { url: scwin.TPL_API, body: b })
    ).then(function (t) {
        var created = !scwin.tplId;
        scwin.fillTemplate(t);
        scwin.toast(created ? "Đã tạo mẫu " + t.templateName + "." : "Đã lưu mẫu.", "success");
        if (created && window.history && window.history.replaceState) {
            window.history.replaceState(null, "", scwin.pageUrl(scwin.DESIGNER_PAGE_PATH(), { templateId: t.templateId, eventId: scwin.getQueryParam("eventId") }));
        }
    }).catch(function (err) {
        var list = [err.message];
        if (err.code === "VALIDATION_ERROR" && err.data && typeof err.data === "object") list = Object.keys(err.data).map(function (k) { return k + ": " + err.data[k]; });
        scwin.showErrors(list);
        scwin.toast(err.message, "error");
    }).then(function () { btn_save.removeClass("is-busy"); });
};
scwin.DESIGNER_PAGE_PATH = function () { return "/printPage/TemplateDesigner.xml"; };

scwin.btn_preview_onclick = function () {
    var b = scwin.buildBody(), errs = scwin.validate(b).filter(function (x) { return x.indexOf("tên mẫu") < 0; });
    if (!b.templateName) b.templateName = "Xem trước";
    if (errs.length) { scwin.showErrors(errs); scwin.toast(errs[0], "warning"); return; }
    scwin.showErrors([]);
    tbx_pvTitle.setValue("Xem trước: " + b.templateName);
    tbx_pvHint.setValue(sbx_pvEvent.getValue() ? "Dữ liệu khách đầu tiên của sự kiện đã chọn." : "Dữ liệu mẫu (Nguyễn Thị Minh Khuê, VIP, bàn A1).");
    scwin.open.pv = true; grp_pvMask.addClass("is-open");
    grp_pvFrame.addClass("is-loading");
    btn_preview.addClass("is-busy");
    scwin.xhr("POST", scwin.TPL_API + "/preview?" + scwin.buildQuery({ eventId: sbx_pvEvent.getValue(), format: "pdf" }), { body: b, responseType: "blob" })
        .then(function (r) {
            if (scwin.pdfUrl) URL.revokeObjectURL(scwin.pdfUrl);
            scwin.pdfUrl = URL.createObjectURL(r.blob);
            var host = scwin.domOf(grp_pvFrame), f = host.querySelector("iframe");
            if (!f) { f = document.createElement("iframe"); f.className = "pr-pdf"; f.title = "Bản xem trước"; host.appendChild(f); }
            f.src = scwin.pdfUrl + "#toolbar=1&navpanes=0";
            grp_pvFrame.addClass("has-pdf");
        }).catch(function (err) { tbx_pvHint.setValue("Không dựng được bản xem trước: " + err.message); })
        .then(function () { grp_pvFrame.removeClass("is-loading"); btn_preview.removeClass("is-busy"); });
};
scwin.closePv = function () { scwin.open.pv = false; grp_pvMask.removeClass("is-open"); };
scwin.btn_pvClose_onclick = scwin.closePv;

scwin.btn_clone_onclick = function () {
    if (!scwin.tplId) { scwin.toast("Lưu mẫu trước khi nhân bản.", "info"); return; }
    if (scwin.dirty && !window.confirm("Thay đổi chưa lưu sẽ không có trong bản sao. Tiếp tục nhân bản?")) return;
    scwin.callApi("sbm_tplClone", { url: scwin.TPL_API + "/" + scwin.tplId + "/clone", body: {} }).then(function (t) {
        scwin.setDirty(false);
        window.location.href = scwin.pageUrl(scwin.DESIGNER_PAGE_PATH(), { templateId: t.templateId, eventId: scwin.getQueryParam("eventId") });
    }).catch(function (err) { scwin.toast(err.message, "error"); });
};
scwin.btn_export_onclick = function () {
    if (!scwin.tplId) { scwin.toast("Lưu mẫu trước khi xuất file.", "info"); return; }
    scwin.downloadFile(scwin.TPL_API + "/" + scwin.tplId + "/export", "MauIn-" + scwin.tplId + ".json", btn_export);
};
scwin.btn_back_onclick = function () {
    if (scwin.dirty && !window.confirm("Mẫu có thay đổi chưa lưu. Rời trang?")) return;
    scwin.dirty = false;
    window.location.href = scwin.pageUrl(scwin.CENTER_PAGE, { tab: "templates", eventId: scwin.getQueryParam("eventId") });
};

/* ---------- Phím tắt ---------- */
scwin.onGlobalKeydown = function (e) {
    if (e.key === "Escape") {
        if (scwin.open.pv) { scwin.closePv(); return; }
        if (scwin.open.preset) { scwin.closePreset(); return; }
        if (scwin.sel >= 0) scwin.selectEl(-1);
        return;
    }
    if ((e.ctrlKey || e.metaKey) && (e.key === "s" || e.key === "S")) { e.preventDefault(); scwin.btn_save_onclick(); return; }
    var tag = (e.target && e.target.tagName || "").toLowerCase();
    if (tag === "input" || tag === "textarea" || tag === "select" || scwin.mode !== "layout") return;
    var el = scwin.els[scwin.sel];
    if (!el) return;
    if (e.key === "Delete" || e.key === "Backspace") { e.preventDefault(); scwin.btn_elDelete_onclick(); return; }
    if ((e.ctrlKey || e.metaKey) && (e.key === "d" || e.key === "D")) { e.preventDefault(); scwin.btn_elDup_onclick(); return; }
    var step = e.shiftKey ? 5 : scwin.SNAP, moved = true;
    if (e.key === "ArrowLeft") el.x = scwin.round(el.x - step);
    else if (e.key === "ArrowRight") el.x = scwin.round(el.x + step);
    else if (e.key === "ArrowUp") el.y = scwin.round(el.y - step);
    else if (e.key === "ArrowDown") el.y = scwin.round(el.y + step);
    else moved = false;
    if (moved) { e.preventDefault(); scwin.setDirty(true); scwin.selectEl(scwin.sel); }
};

