scwin.sbm_tplCreate_submiterror = function (e) { scwin.onSbmError("sbm_tplCreate", e); };
scwin.sbm_tplUpdate_submitdone = function (e) { scwin.onSbmDone("sbm_tplUpdate", e); };
scwin.sbm_tplUpdate_submiterror = function (e) { scwin.onSbmError("sbm_tplUpdate", e); };
scwin.sbm_tplClone_submitdone = function (e) { scwin.onSbmDone("sbm_tplClone", e); };
